use crate::aap::caps::http_client;
use crate::wasi::clocks::wall_clock;

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode a string for use as a query-parameter value.
fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len());
    for &b in input.as_bytes() {
        let unreserved = b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.' | b'~');
        if unreserved {
            out.push(b as char);
        } else {
            out.push('%');
            out.push(HEX[(b >> 4) as usize] as char);
            out.push(HEX[(b & 0x0F) as usize] as char);
        }
    }
    out
}

/// Convert days since 1970-01-01 to a (year, month, day) civil date.
/// Howard Hinnant's `civil_from_days`, specialised to non-negative input.
fn civil_from_days(days: i64) -> (i64, u32, u32) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    if m <= 2 {
        y += 1;
    }
    (y, m, d)
}

/// Format a Unix timestamp as `YYYY-MM-DD`, always exactly 10 characters.
fn date_string(seconds: u64) -> String {
    let days = (seconds / 86_400) as i64;
    let (y, m, d) = civil_from_days(days);
    if y > 9999 {
        // Keep the 10-character contract for timestamps beyond year 9999.
        return String::from("9999-12-31");
    }
    let y = y as u32;
    let mut s = String::with_capacity(10);
    let push2 = |s: &mut String, v: u32| {
        s.push((b'0' + (v / 10) as u8) as char);
        s.push((b'0' + (v % 10) as u8) as char);
    };
    s.push((b'0' + (y / 1000 % 10) as u8) as char);
    s.push((b'0' + (y / 100 % 10) as u8) as char);
    s.push((b'0' + (y / 10 % 10) as u8) as char);
    s.push((b'0' + (y % 10) as u8) as char);
    s.push('-');
    push2(&mut s, m);
    s.push('-');
    push2(&mut s, d);
    s
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        // Enrichment fetch (approved grant extension). A transport failure is
        // returned as a value and ignored; the result does not affect the output.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&tick.reason));
        let _enrichment = http_client::fetch(&url);

        let now = wall_clock::now();
        RunInfo {
            date: date_string(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
